<?php foreach ($rows as $row): ?><?php if ($this->metro->can($current_user->id,'masters.update')): ?><dialog id="edit-district-<?= (int)$row->id ?>" class="admin-modal" aria-labelledby="edit-district-title-<?= (int)$row->id ?>"><div class="modal-head"><div><small><?= e($row->district_code) ?></small><h2 id="edit-district-title-<?= (int)$row->id ?>">Edit kecamatan</h2></div><button type="button" class="modal-close" data-modal-close aria-label="Tutup">×</button></div><form method="post" action="<?= site_url('petugas/master/kecamatan') ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><input type="hidden" name="id" value="<?= (int)$row->id ?>"><div class="modal-body"><div class="form-grid"><label>Kode<input value="<?= e($row->district_code) ?>" disabled></label><label>Nama kecamatan<input name="district_name" required maxlength="120" value="<?= e($row->district_name) ?>"></label><label>Urutan<input type="number" name="sort_order" min="0" value="<?= (int)$row->sort_order ?>"></label></div><label class="master-check"><input type="checkbox" name="is_active" value="1"<?= $row->is_active?' checked':'' ?><?= $this->metro->can($current_user->id,'masters.status')?'':' disabled' ?>> Aktif</label></div><div class="modal-actions"><button type="button" class="button outline" data-modal-close>Batal</button><button class="button primary" type="submit">Simpan perubahan</button></div></form></dialog><?php endif; ?><?php endforeach; ?>
